  <script>
    const TICK = '<svg class="ic" aria-hidden="true"><use href="#i-tick"/></svg>';
    document.getElementById('year').textContent = new Date().getFullYear();
    document.getElementById('todayTitle').textContent = new Date().toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' });

    // Mobile menu
    const menuBtn = document.getElementById('menuBtn'), mobileMenu = document.getElementById('mobileMenu');
    menuBtn.addEventListener('click', () => {
      const open = mobileMenu.classList.toggle('hidden') === false;
      menuBtn.setAttribute('aria-expanded', String(open));
    });
    mobileMenu.querySelectorAll('a').forEach(a => a.addEventListener('click', () => {
      mobileMenu.classList.add('hidden');
      menuBtn.setAttribute('aria-expanded', 'false');
    }));

    // Phone: 7-day chain
    const chain = document.getElementById('chain');
    let todayMark = null;
    for (let i = 0; i < 7; i++) {
      const d = new Date(); d.setDate(d.getDate() - (6 - i));
      const cell = document.createElement('div');
      cell.className = 'day';
      cell.innerHTML = `<span class="box" style="--s:28px" data-on="${i < 6}">${TICK}</span><span>${d.toLocaleDateString(undefined, { weekday: 'narrow' })}</span>`;
      chain.appendChild(cell);
      if (i === 6) todayMark = cell.querySelector('.box');
    }

    // Phone: interactive habits
    const habits = [
      { name: 'Drink 2L of water', meta: 'Health', done: true },
      { name: 'Read 20 pages', meta: 'Learning', done: true },
      { name: 'Meditate 10 min', meta: 'Mindfulness', done: false },
      { name: 'Run 5k', meta: 'Fitness', done: false },
      { name: 'Write in journal', meta: 'Reflection', done: false },
    ];
    const list = document.getElementById('habitList');
    const ring = document.getElementById('ring');
    const C = 2 * Math.PI * 34, baseStreak = 23;

    habits.forEach(h => {
      const li = document.createElement('li');
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'habit';
      b.setAttribute('role', 'checkbox');
      b.setAttribute('aria-checked', String(h.done));
      b.innerHTML = `<span class="box" aria-hidden="true">${TICK}</span><span class="min-w-0 flex-1"><span class="hname">${h.name}</span><span class="hmeta">${h.meta}</span></span>`;
      b.addEventListener('click', () => {
        h.done = !h.done;
        b.setAttribute('aria-checked', String(h.done));
        update();
      });
      li.appendChild(b);
      list.appendChild(li);
    });

    function update() {
      const n = habits.length, done = habits.filter(h => h.done).length, all = done === n;
      ring.style.strokeDashoffset = C * (1 - done / n);
      document.getElementById('pct').textContent = Math.round(done / n * 100) + '%';
      document.getElementById('countLabel').textContent = `${done} of ${n}`;
      document.getElementById('streakNum').textContent = baseStreak + (all ? 1 : 0);
      document.getElementById('streakMsg').textContent = all
        ? `Streak extended to ${baseStreak + 1} days`
        : `${n - done} ${n - done === 1 ? 'habit' : 'habits'} left to extend the streak`;
      todayMark.setAttribute('data-on', String(all));
    }
    update();

    // Heatmap: one series, five steps, ending this week
    const hm = document.getElementById('heatmap'), months = document.getElementById('months');
    const colors = ['rgba(31,27,22,.07)', '#f3d6c2', '#e9aa82', '#d97a45', '#c2410c'];
    const weeks = 30;
    const cols = `repeat(${weeks}, minmax(0, 1fr))`;
    hm.style.gridTemplateColumns = cols;
    hm.style.gridTemplateRows = 'repeat(7, auto)';
    hm.style.gridAutoFlow = 'column';
    months.style.gridTemplateColumns = cols;

    let seed = 7;
    const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const start = new Date(today); start.setDate(start.getDate() - start.getDay() - (weeks - 1) * 7);

    const labels = [];
    for (let w = 0; w < weeks; w++) {
      for (let d = 0; d < 7; d++) {
        const date = new Date(start); date.setDate(start.getDate() + w * 7 + d);
        if (date > today) continue;
        if (date.getDate() === 1) labels.push({ w, text: date.toLocaleDateString(undefined, { month: 'short' }) });
        const p = 0.45 + (w / weeks) * 0.45;
        let lvl = 0;
        if (rnd() < p) lvl = Math.min(4, 1 + Math.floor((rnd() * 0.7 + (w / weeks) * 0.5) * 4));
        const cell = document.createElement('span');
        cell.className = 'block aspect-square rounded-[4px]';
        cell.style.background = colors[lvl];
        cell.title = date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
        hm.appendChild(cell);
      }
    }
    if (labels.length && labels[0].w > 0) {
      const first = new Date(start);
      if (labels[0].w >= 3) labels.unshift({ w: 0, text: first.toLocaleDateString(undefined, { month: 'short' }) });
    }
    labels.forEach(l => {
      const s = document.createElement('span');
      s.className = 'whitespace-nowrap';
      s.style.gridColumn = String(l.w + 1);
      s.textContent = l.text;
